// ---------- bollicine: salgono su tutto il sito, reagiscono a scroll, cursore e tocco ----------
(function(){
  var c=document.getElementById('bubbles');if(!c||!c.getContext)return;
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches){c.style.display='none';return}
  var x=c.getContext('2d'),W=0,H=0,dpr=Math.min(window.devicePixelRatio||1,2),B=[],last=performance.now();
  var N=window.innerWidth<700?50:95,boost=0,lastY=window.scrollY,mt=0;
  function size(){W=innerWidth;H=innerHeight;c.width=W*dpr;c.height=H*dpr;x.setTransform(dpr,0,0,dpr,0,0)}
  function mk(px,py,big){
    var r=big?3+Math.random()*7:(Math.random()<.85?1.5+Math.random()*5:6+Math.random()*10);
    return{x:px==null?Math.random()*W:px,y:py==null?H+r+Math.random()*40:py,r:r,
      v:.25+Math.random()*.55+r*.03,ph:Math.random()*6.28,f:.6+Math.random()*1.4,amp:4+Math.random()*14,
      a:.35+Math.random()*.45,life:px==null?-1:1}
  }
  size();for(var i=0;i<N;i++){var b0=mk();b0.y=Math.random()*H;B.push(b0)}
  addEventListener('resize',size);
  addEventListener('scroll',function(){var y=scrollY;boost=Math.min(boost+Math.abs(y-lastY)*.04,7);lastY=y},{passive:true});
  addEventListener('pointermove',function(e){var n=performance.now();if(n-mt<70||B.length>N+60)return;mt=n;B.push(mk(e.clientX+(Math.random()-.5)*10,e.clientY,true))},{passive:true});
  addEventListener('pointerdown',function(e){for(var k=0;k<12;k++){var b=mk(e.clientX+(Math.random()-.5)*30,e.clientY+(Math.random()-.5)*20,true);b.v+=Math.random()*1.2;B.push(b)}},{passive:true});
  function draw(b){
    var al=b.a*(b.life<0?1:Math.min(1,b.life*2));
    x.beginPath();x.arc(b.x,b.y,b.r,0,6.2832);
    var g=x.createRadialGradient(b.x-b.r*.3,b.y-b.r*.35,b.r*.1,b.x,b.y,b.r);
    g.addColorStop(0,'rgba(255,255,255,'+(al*.35)+')');g.addColorStop(.7,'rgba(140,195,255,'+(al*.08)+')');g.addColorStop(1,'rgba(90,160,255,'+(al*.28)+')');
    x.fillStyle=g;x.fill();
    x.lineWidth=b.r>6?1.2:.9;x.strokeStyle='rgba(170,220,255,'+(al*.75)+')';x.stroke();
    x.beginPath();x.arc(b.x-b.r*.38,b.y-b.r*.38,Math.max(.6,b.r*.22),0,6.2832);x.fillStyle='rgba(255,255,255,'+Math.min(1,al*1.3)+')';x.fill();
  }
  function tick(n){
    var dt=Math.min(3,(n-last)/16.67);last=n;boost*=.94;
    x.clearRect(0,0,W,H);
    for(var i=B.length-1;i>=0;i--){var b=B[i];
      b.ph+=.02*b.f*dt;b.y-=(b.v+boost*(.4+b.r*.05))*dt;b.x+=Math.sin(b.ph)*b.amp*.02*dt;
      if(b.life>0)b.life-=.004*dt;
      if(b.y<-30||(b.life>=0&&b.life<.02)){if(b.life<0&&i<N)B[i]=mk();else B.splice(i,1);continue}
      draw(b);
    }
    requestAnimationFrame(tick);
  }
  document.addEventListener('visibilitychange',function(){last=performance.now()});
  requestAnimationFrame(tick);
})();

